// Pure-JS helpers for the ``ToolDetails`` and ``EventLog``
// truncation rules. Lives outside the JSX file so ``node --test``
// can import it directly (no JSX transformer needed) and so the
// component file stays as close to "render only" as possible.
//
// The same constants are imported by the JSX. Anything that bumps
// these numbers should bump the test expectations in
// ``eventLogTruncation.test.js`` at the same time so we stay
// honest about the bound on rendered DOM nodes.

// Default-collapsed threshold. Tool output up to this many lines
// renders inline without a "show more" toggle.
export const TOOL_DETAILS_COLLAPSE_THRESHOLD = 40;

// Hard ceiling on rendered lines, even with the operator having
// clicked "show full output". A 50K-line ``cat`` or ``find`` would
// otherwise emit 50K spans into the bubble and freeze the tab.
export const TOOL_DETAILS_HARD_CAP = 1000;

// Default window for ``EventLog`` itself. Long sessions accumulate
// thousands of bubbles; we render only the tail by default. The
// stream cache still has the whole history, so "show older" is a
// state flip, not a refetch.
export const EVENT_LOG_WINDOW_SIZE = 200;

// How much more history one "reveal" adds. The log used to jump straight from
// the 200-entry tail to EVERYTHING, which on a long session meant thousands of
// bubbles rendering in one frame — the freeze that made the scroll jump so
// obvious. A chunk keeps each reveal cheap enough to stay smooth, and the
// operator usually only wanted a little more context anyway.
export const EVENT_LOG_CHUNK_SIZE = 100;

export function computeToolDetailsRender(lines, expanded) {
  if (!expanded && lines.length > TOOL_DETAILS_COLLAPSE_THRESHOLD) {
    return {
      visible: lines.slice(0, TOOL_DETAILS_COLLAPSE_THRESHOLD),
      overflowed: false,
    };
  }
  if (lines.length > TOOL_DETAILS_HARD_CAP) {
    return {
      visible: lines.slice(0, TOOL_DETAILS_HARD_CAP),
      overflowed: true,
    };
  }
  return { visible: lines, overflowed: false };
}

// ``isTurnBoundary`` (optional) marks the entries that render as a
// "YOU ASKED" prompt header. When given, the trailing window is extended
// BACKWARD to the boundary that opens the turn the cut falls inside — so
// the latest turn always shows its header. Without this, a single turn
// longer than the window (a big agent turn with hundreds of tool events)
// starts the window mid-turn, hiding the prompt until the operator clicks
// "show older" — and that's exactly the state a fresh page load lands in:
// the in-memory stream cache is empty, so the transcript replays from
// history straight into the windowed tail with no header on screen.
export function computeEventLogWindow(
  entries, showAll, isTurnBoundary, windowSize = EVENT_LOG_WINDOW_SIZE,
) {
  const size = Number.isFinite(windowSize) && windowSize > 0
    ? windowSize
    : EVENT_LOG_WINDOW_SIZE;
  if (showAll || entries.length <= size) {
    return { visible: entries, hidden: 0 };
  }
  let start = entries.length - size;
  if (typeof isTurnBoundary === 'function' && start > 0) {
    let boundary = start;
    while (boundary > 0 && !isTurnBoundary(entries[boundary])) {
      boundary -= 1;
    }
    // Only snap when we actually landed on a boundary. If nothing before
    // the cut is a prompt (e.g. autonomous preamble), keep the plain tail —
    // there's no header to preserve there anyway.
    if (isTurnBoundary(entries[boundary])) {
      start = boundary;
    }
  }
  return {
    visible: entries.slice(start),
    hidden: start,
  };
}
